contract InvMutTest {
    C c;
    address public lastCreated;

    constructor(C _c) { c = _c; }

    // run tries calling create and checks the general property:
    // - If msg.sender (this contract) is NOT a program operator, create must revert.
    // - If this contract IS a program operator and c.roundImplementation() and c.alloSettings() are non-zero,
    //   then create must succeed, return a non-zero address, and c.roundImplementation()/alloSettings() remain unchanged.
    // Note: we cannot call c.create as a different msg.sender; the test contract is the caller.
    function run(bytes calldata encodedParameters, address ownedBy, bool makeOperator) public payable {
        require(true);

        // record prior values
        address beforeImpl = c.roundImplementation();
        address beforeSettings = c.alloSettings();

        // ensure this contract is (or isn't) a program operator by calling c.programOperators setter via owner-only functions is not available,
        // but the factory exposes programOperators mapping public: we cannot mutate it directly. So we use the provided external surface:
        // The only way to make this contract a program operator is if the freshly deployed C had it set; the checker deploys a fresh c,
        // but we must express a general rule: if programOperators[this]==false then create reverts; else if true and impl/settings non-zero then create returns non-zero and impl/settings unchanged.

        bool wasOperator = c.programOperators(address(this));

        bool reverted;
        address created;
        // Call create and catch revert
        try c.create(encodedParameters, ownedBy) returns (address addr) {
            reverted = false;
            created = addr;
        } catch {
            reverted = true;
            created = address(0);
        }

        // After call, read values again
        address afterImpl = c.roundImplementation();
        address afterSettings = c.alloSettings();

        // General rule expressed in one assert:
        // If we were not a program operator, the call must have reverted.
        // If we were an operator and both impl and settings were non-zero before, the call must not revert, must return non-zero, and impl/settings unchanged.
        assert(
            (wasOperator == false && reverted == true)
            || (wasOperator == true && beforeImpl != address(0) && beforeSettings != address(0) && reverted == false && created != address(0) && afterImpl == beforeImpl && afterSettings == beforeSettings)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Test: owner-only updateRoundImplementation should revert when passed zero,
    // and when called with a non-zero address by the owner it must set roundImplementation()
    // to that address (observable via the public getter) and not leave it as zero.
    // Because only the owner can call, this test assumes that the freshly deployed c's owner is this contract
    // (the checker deploys c and then deploys this test passing c). To be safe we express behavior using try/catch
    // and observable getter c.roundImplementation().
    function run(address newImpl) public payable {
        require(newImpl != address(0) || newImpl == address(0), true); // allow any input; placeholder to satisfy template

        // read before value
        address before = c.roundImplementation();

        bool reverted;
        try c.updateRoundImplementation(payable(newImpl)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address after = c.roundImplementation();

        // General property:
        // - If call reverted then it must be that newImpl == address(0) OR caller was not owner; we cannot observe owner check directly,
        //   but we can require that if the call succeeded (not reverted) then after == newImpl and newImpl != address(0).
        // - Conversely, if newImpl == address(0) then the call must revert (per contract require).
        // We express a single assert covering these implications.
        assert(
            // If call succeeded then newImpl must be non-zero and the getter equals newImpl
            (reverted == false && newImpl != address(0) && after == newImpl)
            // If newImpl is zero then call must have reverted (contract requires non-zero)
            || (newImpl == address(0) && reverted == true)
            // If call reverted but newImpl was non-zero, this can only be explained by caller not being owner;
            // we allow that case as well (so include it as a permitted outcome)
            || (reverted == true && newImpl != address(0))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // One public function with all test logic
    function run(address newAllo) public payable {
        require(true);

        // read before value
        address before = c.alloSettings();

        bool reverted;
        try c.updateAlloSettings(newAllo) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after value
        address after = c.alloSettings();

        // General property asserted:
        // - If the call succeeded (did not revert) then the public getter must equal the new value (owner successfully updated it).
        // - If the call reverted then we allow that (caller not owner); in that case the getter must remain equal to the previous value.
        // This is a single assert expressing both possibilities.
        assert(
            (!reverted && after == newAllo)
            || (reverted && after == before)
        );
    }

    receive() external payable {}
}

